package history
import"testing"
func TestBuildVerifiesDigestAndPreservesMissingSignals(t *testing.T){c:=Content{Repository:"o/r",Revision:"a",CreatedAt:"2026",Signals:[]Signal{{Name:"coverage",Value:80,Scale:"percent",Provenance:"ci"}}};r:=Receipt{SchemaVersion:"1.0.0",Digest:Digest(c),Content:c};report,err:=Build([]Receipt{r});if err!=nil||len(report.Receipts[0].Content.Signals)!=1{t.Fatal(err)};r.Content.Revision="b";if _,err:=Build([]Receipt{r});err==nil{t.Fatal("expected tamper rejection")}}
func TestBuildRejectsNilSignals(t *testing.T){c:=Content{Repository:"o/r",Revision:"b",CreatedAt:"2",Signals:nil};if _,err:=Build([]Receipt{{SchemaVersion:"1.0.0",Digest:Digest(c),Content:c}});err==nil{t.Fatal("expected nil signals rejection")}}
func TestParseReceiptRejectsOmittedAndNullSignals(t *testing.T){for _,body:=range []string{`{"schema_version":"1.0.0","digest":"x","content":{"repository":"o/r","revision":"r","created_at":"t"}}`,`{"schema_version":"1.0.0","digest":"x","content":{"repository":"o/r","revision":"r","created_at":"t","signals":null}}`}{if _,err:=ParseReceipt([]byte(body));err==nil{t.Fatalf("expected signals rejection: %s",body)}}}
func TestTrendOrderingIncludesScale(t *testing.T){c:=Content{Repository:"o/r",Revision:"a",CreatedAt:"1",Signals:[]Signal{{Name:"x",Scale:"z",Provenance:"a"},{Name:"x",Scale:"a",Provenance:"z"}}};report,err:=Build([]Receipt{{SchemaVersion:"1.0.0",Digest:Digest(c),Content:c}});if err!=nil||report.Trends[0].Scale!="a"{t.Fatalf("%+v %v",report,err)}}
func TestStrictHistoryEOF(t *testing.T){if _,err:=ParseReceipt([]byte(`{"schema_version":"1.0.0","digest":"x","content":{"signals":[]}} {}`));err==nil{t.Fatal("expected trailing rejection")};if _,err:=ParseApproval([]byte(`{"schema_version":"1.0.0","repository":"o/r","receipt_digests":["x"]} {}`));err==nil{t.Fatal("expected trailing rejection")}}
